package registry

import (
	"fmt"
	"strings"
	"time"
)

// The range of TCP ports a service may register with.
const (
	minPort = 1
	maxPort = 65535
)

// Service is one running instance of a service. Callers fill in Name, Address
// and Port; the registry sets the remaining fields when the instance registers.
type Service struct {
	// ID identifies this instance and is generated by the registry.
	ID string
	// Name groups instances of the same service, such as "orders".
	Name string
	// Address is the host name or IP address where the instance is reachable.
	Address string
	// Port is the TCP port the instance listens on.
	Port int
	// RegisteredAt is when the instance first registered.
	RegisteredAt time.Time
	// LastHeartbeat is when the instance last proved it was alive.
	LastHeartbeat time.Time
}

// validate checks the fields a caller supplies when registering a service.
// The returned error wraps ErrInvalidService.
func (service *Service) validate() error {
	if service == nil {
		return fmt.Errorf("%w: service is required", ErrInvalidService)
	}

	if strings.TrimSpace(service.Name) == "" {
		return fmt.Errorf("%w: name is required", ErrInvalidService)
	}

	if strings.TrimSpace(service.Address) == "" {
		return fmt.Errorf("%w: address is required", ErrInvalidService)
	}

	if service.Port < minPort || service.Port > maxPort {
		return fmt.Errorf("%w: port must be between %d and %d", ErrInvalidService, minPort, maxPort)
	}

	return nil
}
